export const ROUTE_NAMES = Object.entries(ENCOUNTERS_DATA).map(([key, data]) => ({
  key,
  name_es: data.name_es,
  name_en: data.name_en,
  gen: data.gen,
}));

export function getPokemonId(name) {
  return POKEMON_IDS[name] || POKEMON_IDS[name.toLowerCase()] || null;
}

export function getRoutesByPokemon(pokemonName, genFilter = 'all') {
  const lower = pokemonName.toLowerCase();
  const results = [];
  for (const [routeKey, data] of Object.entries(ENCOUNTERS_DATA)) {
    let encounters = data.encounters.filter(e => e.pokemon.toLowerCase() === lower);
    if (genFilter !== 'all') {
      encounters = encounters.filter(e => e.gen === parseInt(genFilter));
    }
    if (encounters.length > 0) {
      results.push({ routeKey, routeName: data, encounters });
    }
  }
  return results;
}

export function searchRoutes(query, genFilter = 'all') {
  const lower = query.toLowerCase();
  return Object.entries(ENCOUNTERS_DATA)
    .filter(([key, data]) =>
      data.name_es.toLowerCase().includes(lower) ||
      data.name_en.toLowerCase().includes(lower) ||
      key.toLowerCase().includes(lower)
    )
    .map(([key, data]) => {
      let encounters = data.encounters;
      if (genFilter !== 'all') {
        encounters = encounters.filter(e => e.gen === parseInt(genFilter));
      }
      return { routeKey: key, ...data, encounters };
    })
    .filter(r => r.encounters.length > 0);
}
